css:
:host {
  --ink: #2d2d2d;
  --muted: #666;
  --accent: #0055aa;
  --warm: #cc5500;
  --line: #e0e0e0;
  --paper: #f9f9f9;
  --glass: rgba(255, 255, 255, 0.7);
  --glass-border: rgba(255, 255, 255, 0.9);
  --success: #2e7d32;
  --fail: #c62828;
}

.lab-workbench {
  font-family: system-ui, -apple-system, sans-serif;
  color: var(--ink);
  background: var(--paper);
  padding: 2rem;
  max-width: 900px;
  margin: 0 auto;
  line-height: 1.6;
}

.section-header {
  margin-bottom: 2rem;
  border-bottom: 2px solid var(--ink);
  padding-bottom: 1rem;
}

.section-title {
  font-size: 2rem;
  margin: 0 0 0.5rem 0;
  color: var(--ink);
}

.section-lead {
  font-size: 1.1rem;
  color: var(--muted);
  margin: 0;
}

.simulation-container {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 1.5rem;
  margin-bottom: 2rem;
}

@media (max-width: 600px) {
  .simulation-container {
    grid-template-columns: 1fr;
  }
}

.glass-card {
  background: var(--glass);
  border: 1px solid var(--glass-border);
  border-radius: 8px;
  padding: 1.5rem;
  box-shadow: 0 4px 6px rgba(0,0,0,0.05);
  backdrop-filter: blur(4px);
}

.control-group {
  margin-bottom: 1rem;
}

.control-group label {
  display: block;
  font-size: 0.9rem;
  color: var(--muted);
  margin-bottom: 0.25rem;
}

select, button {
  width: 100%;
  padding: 0.5rem;
  font-size: 1rem;
  border-radius: 4px;
  border: 1px solid var(--line);
  background: #fff;
  margin-bottom: 0.5rem;
}

.primary-btn {
  background: var(--accent);
  color: #fff;
  border: none;
  font-weight: bold;
  cursor: pointer;
  transition: opacity 0.2s;
}

.primary-btn:hover {
  opacity: 0.9;
}

.secondary-btn {
  background: transparent;
  color: var(--muted);
  border: 1px solid var(--line);
  cursor: pointer;
}

.secondary-btn:hover {
  background: rgba(0,0,0,0.05);
}

.status-display {
  display: flex;
  align-items: center;
  margin-bottom: 1rem;
  font-weight: bold;
}

.status-indicator {
  width: 12px;
  height: 12px;
  border-radius: 50%;
  background: #ccc;
  margin-right: 0.5rem;
  transition: background 0.3s;
}

.data-stream {
  display: flex;
  justify-content: space-around;
  height: 150px;
  align-items: flex-end;
  margin-bottom: 1rem;
  border-bottom: 1px solid var(--line);
  padding-bottom: 0.5rem;
}

.stream-channel {
  width: 40%;
  display: flex;
  flex-direction: column;
  align-items: center;
  position: relative;
}

.channel-label {
  font-size: 0.75rem;
  color: var(--muted);
  margin-bottom: 0.5rem;
  text-align: center;
}

.flow-bar {
  width: 100%;
  background: var(--line);
  transition: height 0.5s ease, background 0.3s;
  border-radius: 4px 4px 0 0;
  min-height: 2px;
}

.parametric .flow-bar {
  background: var(--accent);
  opacity: 0.3;
}

.non-parametric .flow-bar {
  background: var(--warm);
  opacity: 0.8;
}

.result-metric {
  text-align: center;
  font-size: 1.5rem;
  font-weight: bold;
  color: var(--ink);
}

.metric-label {
  display: block;
  font-size: 0.9rem;
  color: var(--muted);
  font-weight: normal;
}

.evidence-table-container {
  margin-top: 2rem;
  overflow-x: auto;
}

.evidence-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 0.95rem;
  background: #fff;
  border: 1px solid var(--line);
}

.evidence-table th, .evidence-table td {
  padding: 0.75rem;
  text-align: left;
  border-bottom: 1px solid var(--line);
}

.evidence-table th {
  background: #f0f0f0;
  font-weight: 600;
}

.table-note {
  font-size: 0.85rem;
  color: var(--muted);
  margin-top: 0.5rem;
  font-style: italic;
}

.conclusion-block {
  margin-top: 2rem;
  padding: 1.5rem;
  background: #fff;
  border-left: 4px solid var(--accent);
  border-radius: 0 4px 4px 0;
}

.conclusion-block h3 {
  margin-top: 0;
  font-size: 1.2rem;
}

.source-btn {
  width: auto;
  padding: 0.25rem 0.75rem;
  font-size: 0.85rem;
  margin-top: 1rem;
  background: #f0f0f0;
  border: 1px solid #ddd;
  cursor: pointer;
}

.source-btn:hover {
  background: #e0e0e0;
}

javascript:
(function() {
  const runBtn = document.getElementById('run-sim-btn');
  const resetBtn = document.getElementById('reset-sim-btn');
  const indexSelect = document.getElementById('index-year');
  const querySelect = document.getElementById('query-time');
  const statusText = document.getElementById('status-text');
  const statusIndicator = document.getElementById('match-status');
  const accuracyVal = document.getElementById('accuracy-val');
  const npFlow = document.getElementById('np-flow');
  const tableBody = document.getElementById('table-body');

  // Data from S157 (p.8)
  const experimentData = {
    '2016-2016': { match: true, acc: '70%', note: 'Match' },
    '2018-2018': { match: true, acc: '68%', note: 'Match' },
    '2018-2016': { match: false, acc: '12%', note: 'Mismatch' },
    '2016-2018': { match: false, acc: '4%', note: 'Mismatch' }
  };

  function updateSimulation() {
    const indexYear = indexSelect.value;
    const queryYear = querySelect.value;
    const key = `${indexYear}-${queryYear}`;
    const data = experimentData[key];

    if (!data) return;

    // Update Status
    if (data.match) {
      statusText.textContent = '索引与查询时间匹配';
      statusText.style.color = 'var(--success)';
      statusIndicator.style.background = 'var(--success)';
      npFlow.style.height = '80%';
      npFlow.style.background = 'var(--success)';
    } else {
      statusText.textContent = '索引与查询时间不匹配';
      statusText.style.color = 'var(--fail)';
      statusIndicator.style.background = 'var(--fail)';
      npFlow.style.height = '15%';
      npFlow.style.background = 'var(--fail)';
    }

    // Update Metric
    accuracyVal.textContent = data.acc;

    // Update Table
    renderTable();
  }

  function renderTable() {
    tableBody.innerHTML = '';
    const indexYear = indexSelect.value;
    const queryYear = querySelect.value;
    const currentKey = `${indexYear}-${queryYear}`;
    const currentData = experimentData[currentKey];

    // Show all 4 scenarios for context, highlight current
    Object.keys(experimentData).forEach(key => {
      const row = experimentData[key];
      const tr = document.createElement('tr');
      if (key === currentKey) {
        tr.style.background = '#f0f8ff';
        tr.style.fontWeight = 'bold';
      }

      const [iYear, qYear] = key.split('-');
      tr.innerHTML = `
        <td>${iYear}</td>
        <td>${qYear}</td>
        <td>${row.note}</td>
        <td>${row.acc}</td>
        <td><button type="button" class="source-btn" data-source="S157" style="width:auto;padding:2px 6px;font-size:0.75rem;margin:0;">原文</button></td>
      `;
      tableBody.appendChild(tr);
    });
  }

  function resetSimulation() {
    indexSelect.value = '2016';
    querySelect.value = '2016';
    statusText.textContent = '等待输入...';
    statusText.style.color = 'var(--ink)';
    statusIndicator.style.background = '#ccc';
    accuracyVal.textContent = '--';
    npFlow.style.height = '0%';
    npFlow.style.background = 'var(--warm)';
    tableBody.innerHTML = '';
  }

  runBtn.addEventListener('click', updateSimulation);
  resetBtn.addEventListener('click', resetSimulation);

  // Initialize table with empty state or default
  renderTable();
})();
